}
```

### Vue + Nuxt

```ts
// plugins/domos.client.ts
import { defineNuxtPlugin } from '#app';
import { DomOSPlugin } from '@domos/vue';

export default defineNuxtPlugin((nuxtApp) => {
  nuxtApp.vueApp.use(DomOSPlugin, {
